import { useState } from 'react'
import { Button, Title2, makeStyles, tokens } from '@fluentui/react-components'
import type { Card, Lane as LaneData } from '../../hooks/useBoard'
import type { BoardRole } from '../../hooks/useBoards'
import CardItem from './CardItem'
import AddCardForm from './AddCardForm'
import CardDetailDialog from './CardDetailDialog'

const useStyles = makeStyles({
  lane: {
    minWidth: '260px',
    maxWidth: '320px',
    backgroundColor: tokens.colorNeutralBackground2,
    borderRadius: tokens.borderRadiusMedium,
    padding: tokens.spacingVerticalM,
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalS,
  },
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  cards: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalXS,
  },
  emptySlot: {
    height: '40px',
    borderRadius: tokens.borderRadiusMedium,
    border: `1px dashed ${tokens.colorNeutralStroke2}`,
  },
})

interface LaneProps {
  lane: LaneData
  callerRole: BoardRole
  onDelete: (boardId: string, laneId: string) => void
}

export default function Lane({ lane, callerRole, onDelete }: LaneProps) {
  const styles = useStyles()
  const canModify = callerRole === 'Owner' || callerRole === 'Member'
  const [editingCard, setEditingCard] = useState<Card | null>(null)

  const sortedCards = [...lane.cards].sort((a, b) => a.position - b.position)

  return (
    <section className={styles.lane} aria-label={`Lane: ${lane.name}`}>
      <div className={styles.header}>
        <Title2 as="h2">{lane.name}</Title2>
        {canModify && (
          <Button
            size="small"
            appearance="subtle"
            aria-label={`Delete lane ${lane.name}`}
            onClick={() => onDelete(lane.boardId, lane.id)}
          >
            Delete
          </Button>
        )}
      </div>
      <div className={styles.cards}>
        {sortedCards.length === 0 && !canModify && (
          <div className={styles.emptySlot} aria-hidden="true" />
        )}
        {sortedCards.map((card) => (
          <CardItem
            key={card.id}
            card={card}
            callerRole={callerRole}
            onEdit={setEditingCard}
          />
        ))}
      </div>
      {canModify && <AddCardForm boardId={lane.boardId} laneId={lane.id} />}
      {editingCard && (
        <CardDetailDialog
          card={editingCard}
          open={true}
          onClose={() => setEditingCard(null)}
        />
      )}
    </section>
  )
}

import { test, expect } from '@playwright/test'
import { ADMIN_AUTH, API_BASE, WEB_BASE } from '../auth.helpers'

// ── US1: Admin creates a board and adds lanes ─────────────────────────────────

test.describe('US1: Admin creates a board and adds lanes', () => {
  test.use({ storageState: ADMIN_AUTH })

  test('scenario 1 — admin creates a board and is assigned Owner role', async ({ page }) => {
    await page.goto(`${WEB_BASE}/`)
    await expect(page.getByRole('heading', { level: 1 })).toBeVisible()

    await page.getByRole('button', { name: /create board/i }).click()
    const nameInput = page.getByRole('textbox', { name: /board name/i })
    await nameInput.fill('Scenario 1 Board')
    await page.getByRole('button', { name: /^create$/i }).click()

    await expect(page).toHaveURL(/\/boards\/[0-9a-f-]+/, { timeout: 10_000 })
    await expect(page.getByRole('heading', { name: 'Scenario 1 Board' })).toBeVisible()
  })

  test('scenario 2 — admin adds three lanes and they appear in insertion order', async ({
    page,
    request,
  }) => {
    const boardName = `Lane Order Board ${Date.now()}`
    const createResp = await request.post(`${API_BASE}/api/v1/boards`, {
      data: { name: boardName },
    })
    expect(createResp.ok()).toBeTruthy()
    const board = await createResp.json()

    await page.goto(`${WEB_BASE}/boards/${board.id}`)
    await expect(page.getByRole('heading', { name: boardName })).toBeVisible()

    for (const laneName of ['To Do', 'In Progress', 'Done']) {
      await page.getByRole('button', { name: /add lane/i }).click()
      await page.getByRole('textbox', { name: /lane name/i }).fill(laneName)
      await page.getByRole('button', { name: /^add$/i }).click()
      await expect(page.getByRole('heading', { name: laneName })).toBeVisible()
    }

    const lanes = page.getByRole('region', { name: /lane/i })
    await expect(lanes.nth(0)).toContainText('To Do')
    await expect(lanes.nth(1)).toContainText('In Progress')
    await expect(lanes.nth(2)).toContainText('Done')
  })

  test('scenario 3 — board list shows the newly created board', async ({ page, request }) => {
    const boardName = `Listed Board ${Date.now()}`
    await request.post(`${API_BASE}/api/v1/boards`, { data: { name: boardName } })

    await page.goto(`${WEB_BASE}/`)
    await expect(page.getByText(boardName)).toBeVisible({ timeout: 10_000 })
  })

  test('scenario 4 — duplicate board name is rejected with conflict error', async ({
    page,
    request,
  }) => {
    const boardName = `Duplicate Board ${Date.now()}`
    await request.post(`${API_BASE}/api/v1/boards`, { data: { name: boardName } })

    await page.goto(`${WEB_BASE}/`)
    await page.getByRole('button', { name: /create board/i }).click()
    await page.getByRole('textbox', { name: /board name/i }).fill(boardName)
    await page.getByRole('button', { name: /^create$/i }).click()

    await expect(page.getByRole('alert')).toBeVisible({ timeout: 10_000 })
  })

  test('scenario 5 — duplicate lane name within a board is rejected', async ({
    page,
    request,
  }) => {
    const boardName = `Dup Lane Board ${Date.now()}`
    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, {
      data: { name: boardName },
    })
    const board = await boardResp.json()

    await page.goto(`${WEB_BASE}/boards/${board.id}`)
    await page.getByRole('button', { name: /add lane/i }).click()
    await page.getByRole('textbox', { name: /lane name/i }).fill('Backlog')
    await page.getByRole('button', { name: /^add$/i }).click()
    await expect(page.getByRole('heading', { name: 'Backlog' })).toBeVisible()

    await page.getByRole('button', { name: /add lane/i }).click()
    await page.getByRole('textbox', { name: /lane name/i }).fill('Backlog')
    await page.getByRole('button', { name: /^add$/i }).click()

    await expect(page.getByRole('alert')).toBeVisible({ timeout: 10_000 })
  })
})

// ── US1: Non-admin cannot create boards ──────────────────────────────────────

test.describe('US1: Non-admin user cannot create boards', () => {
  test('scenario 6 — non-admin sees no create board button', async ({ browser, request }) => {
    const uniqueEmail = `member-${Date.now()}@example.com`
    const ctx = await browser.newContext()
    const page = await ctx.newPage()

    await page.goto(
      `${API_BASE}/api/v1/dev/authenticate?email=${encodeURIComponent(uniqueEmail)}&displayName=Member+User`,
    )
    await page.waitForURL(`${WEB_BASE}/**`)

    await page.goto(`${WEB_BASE}/`)

    await expect(page.getByRole('button', { name: /create board/i })).not.toBeVisible()

    await ctx.close()
  })
})

import { useState } from 'react'
import {
  Button,
  Field,
  Input,
  MessageBar,
  makeStyles,
  tokens,
} from '@fluentui/react-components'
import { useCreateCard } from '../../hooks/useCreateCard'

const useStyles = makeStyles({
  root: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalS,
    marginTop: tokens.spacingVerticalS,
  },
  actions: {
    display: 'flex',
    gap: tokens.spacingHorizontalS,
  },
})

interface AddCardFormProps {
  boardId: string
  laneId: string
}

export default function AddCardForm({ boardId, laneId }: AddCardFormProps) {
  const styles = useStyles()
  const [open, setOpen] = useState(false)
  const [title, setTitle] = useState('')
  const [titleError, setTitleError] = useState(false)
  const createCard = useCreateCard()

  const handleSubmit = () => {
    if (!title.trim()) {
      setTitleError(true)
      return
    }
    setTitleError(false)
    createCard.mutate(
      { boardId, laneId, title: title.trim() },
      {
        onSuccess: () => {
          setTitle('')
          setOpen(false)
        },
      },
    )
  }

  if (!open) {
    return (
      <Button
        appearance="subtle"
        size="small"
        onClick={() => setOpen(true)}
        aria-label="Add card"
      >
        + Add card
      </Button>
    )
  }

  return (
    <div className={styles.root}>
      {(titleError || createCard.isError) && (
        <MessageBar role="alert" intent="error">
          {titleError ? 'Card title is required.' : 'Failed to add card. Please try again.'}
        </MessageBar>
      )}
      <Field label="Card title">
        <Input
          aria-label="Card title"
          value={title}
          onChange={(_, d) => setTitle(d.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter') handleSubmit()
            if (e.key === 'Escape') setOpen(false)
          }}
          autoFocus
        />
      </Field>
      <div className={styles.actions}>
        <Button
          appearance="primary"
          size="small"
          onClick={handleSubmit}
          disabled={createCard.isPending}
        >
          Add
        </Button>
        <Button
          appearance="subtle"
          size="small"
          onClick={() => {
            setOpen(false)
            setTitle('')
          }}
        >
          Cancel
        </Button>
      </div>
    </div>
  )
}

import { test, expect } from '@playwright/test'
import { ADMIN_AUTH, API_BASE, WEB_BASE } from '../auth.helpers'

// ── US2: Board member adds and manages cards ──────────────────────────────────

test.describe('US2: Board member adds and manages cards', () => {
  test.use({ storageState: ADMIN_AUTH })

  test('scenario 1 — member adds a card to a lane and it appears', async ({ page, request }) => {
    const boardName = `Card Board ${Date.now()}`
    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, { data: { name: boardName } })
    expect(boardResp.ok()).toBeTruthy()
    const board = await boardResp.json()
    const laneResp = await request.post(`${API_BASE}/api/v1/boards/${board.id}/lanes`, {
      data: { name: 'To Do' },
    })
    expect(laneResp.ok()).toBeTruthy()

    await page.goto(`${WEB_BASE}/boards/${board.id}`)
    await expect(page.getByRole('heading', { name: boardName })).toBeVisible()

    await page.getByRole('button', { name: /add card/i }).first().click()
    await page.getByRole('textbox', { name: /card title/i }).fill('My First Card')
    await page.getByRole('button', { name: /^add$/i }).click()

    await expect(page.getByText('My First Card')).toBeVisible({ timeout: 10_000 })
  })

  test('scenario 2 — member updates title, description, and due date', async ({
    page,
    request,
  }) => {
    const boardName = `Update Card Board ${Date.now()}`
    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, { data: { name: boardName } })
    const board = await boardResp.json()
    const laneResp = await request.post(`${API_BASE}/api/v1/boards/${board.id}/lanes`, {
      data: { name: 'Work' },
    })
    const lane = await laneResp.json()
    const cardResp = await request.post(
      `${API_BASE}/api/v1/boards/${board.id}/lanes/${lane.id}/cards`,
      { data: { title: 'Original Title' } },
    )
    expect(cardResp.ok()).toBeTruthy()

    await page.goto(`${WEB_BASE}/boards/${board.id}`)
    await expect(page.getByText('Original Title')).toBeVisible({ timeout: 10_000 })

    await page.getByRole('button', { name: /edit card/i }).first().click()
    await page.getByRole('textbox', { name: /title/i }).fill('Updated Title')
    await page.getByRole('textbox', { name: /description/i }).fill('A new description')
    await page.getByRole('button', { name: /save/i }).click()

    await expect(page.getByText('Updated Title')).toBeVisible({ timeout: 10_000 })
  })

  test('scenario 3 — member explicitly clears a card due date', async ({ page, request }) => {
    const boardName = `Due Date Board ${Date.now()}`
    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, { data: { name: boardName } })
    const board = await boardResp.json()
    const laneResp = await request.post(`${API_BASE}/api/v1/boards/${board.id}/lanes`, {
      data: { name: 'Work' },
    })
    const lane = await laneResp.json()
    const cardResp = await request.post(
      `${API_BASE}/api/v1/boards/${board.id}/lanes/${lane.id}/cards`,
      { data: { title: 'Task With Due Date', dueDate: '2099-12-31' } },
    )
    expect(cardResp.ok()).toBeTruthy()

    await page.goto(`${WEB_BASE}/boards/${board.id}`)
    await expect(page.getByText('Task With Due Date')).toBeVisible({ timeout: 10_000 })

    await page.getByRole('button', { name: /edit card/i }).first().click()
    await page.getByRole('checkbox', { name: /clear due date/i }).check()
    await page.getByRole('button', { name: /save/i }).click()

    await page.getByRole('button', { name: /edit card/i }).first().click()
    const dueDateField = page.getByRole('textbox', { name: /due date/i })
    await expect(dueDateField).toHaveValue('')
  })

  test('scenario 4 — delete card leaves remaining positions gapless', async ({
    page,
    request,
  }) => {
    const boardName = `Delete Card Board ${Date.now()}`
    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, { data: { name: boardName } })
    const board = await boardResp.json()
    const laneResp = await request.post(`${API_BASE}/api/v1/boards/${board.id}/lanes`, {
      data: { name: 'Work' },
    })
    const lane = await laneResp.json()
    for (const title of ['Card Alpha', 'Card Beta', 'Card Gamma']) {
      const resp = await request.post(
        `${API_BASE}/api/v1/boards/${board.id}/lanes/${lane.id}/cards`,
        { data: { title } },
      )
      expect(resp.ok()).toBeTruthy()
    }

    await page.goto(`${WEB_BASE}/boards/${board.id}`)
    await expect(page.getByText('Card Alpha')).toBeVisible({ timeout: 10_000 })

    await page.getByRole('button', { name: /delete card/i }).first().click()
    await page.getByRole('button', { name: /confirm/i }).click()

    await expect(page.getByText('Card Alpha')).not.toBeVisible({ timeout: 10_000 })
    await expect(page.getByText('Card Beta')).toBeVisible()
    await expect(page.getByText('Card Gamma')).toBeVisible()

    // Verify gapless positions via API
    const boardDetailResp = await request.get(`${API_BASE}/api/v1/boards/${board.id}`)
    const boardDetail = await boardDetailResp.json()
    const positions = boardDetail.lanes[0].cards.map((c: { position: number }) => c.position)
    expect(positions).toEqual([1, 2])
  })

  test('scenario 5 — viewer role add-card request returns 403', async ({ request, browser }) => {
    const viewerEmail = `e2e-viewer-${Date.now()}@example.com`

    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, {
      data: { name: `Viewer Forbidden Board ${Date.now()}` },
    })
    const board = await boardResp.json()
    const laneResp = await request.post(`${API_BASE}/api/v1/boards/${board.id}/lanes`, {
      data: { name: 'Lane' },
    })
    const lane = await laneResp.json()

    // Add viewer to the board via dev seed endpoint (implemented alongside CardEndpoints)
    const seedResp = await request.post(`${API_BASE}/api/v1/dev/seed-board-member`, {
      data: { email: viewerEmail, boardId: board.id, role: 'Viewer' },
    })
    expect(seedResp.ok()).toBeTruthy()

    const viewerCtx = await browser.newContext()
    const viewerPage = await viewerCtx.newPage()
    await viewerPage.goto(
      `${API_BASE}/api/v1/dev/authenticate?email=${encodeURIComponent(viewerEmail)}&displayName=Viewer+User`,
    )
    await viewerPage.waitForURL(`${WEB_BASE}/**`)

    const forbiddenResp = await viewerPage.request.post(
      `${API_BASE}/api/v1/boards/${board.id}/lanes/${lane.id}/cards`,
      { data: { title: 'Viewer Should Not Create This' } },
    )
    expect(forbiddenResp.status()).toBe(403)

    await viewerCtx.close()
  })

  test('scenario 6 — empty card title is rejected with validation error', async ({
    page,
    request,
  }) => {
    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, {
      data: { name: `Title Val Board ${Date.now()}` },
    })
    const board = await boardResp.json()
    await request.post(`${API_BASE}/api/v1/boards/${board.id}/lanes`, { data: { name: 'Lane' } })

    await page.goto(`${WEB_BASE}/boards/${board.id}`)
    await expect(page.getByRole('heading', { name: board.name })).toBeVisible()

    await page.getByRole('button', { name: /add card/i }).first().click()
    await page.getByRole('textbox', { name: /card title/i }).fill('')
    await page.getByRole('button', { name: /^add$/i }).click()

    await expect(page.getByRole('alert')).toBeVisible({ timeout: 10_000 })
  })
})

import {
  FluentProvider,
  Spinner,
  Title1,
  makeStyles,
  tokens,
  webLightTheme,
} from '@fluentui/react-components'
import { useParams } from 'react-router-dom'
import { useBoard } from '../hooks/useBoard'
import { useCurrentUser } from '../hooks/useCurrentUser'
import { useDeleteLane } from '../hooks/useDeleteLane'
import Lane from '../components/board/Lane'
import AddLaneForm from '../components/board/AddLaneForm'

const useStyles = makeStyles({
  root: {
    padding: tokens.spacingHorizontalXXL,
    overflowX: 'auto',
  },
  header: {
    marginBottom: tokens.spacingVerticalL,
  },
  lanes: {
    display: 'flex',
    gap: tokens.spacingHorizontalM,
    alignItems: 'flex-start',
    overflowX: 'auto',
    paddingBottom: tokens.spacingVerticalM,
  },
})

export default function BoardPage() {
  const styles = useStyles()
  const { boardId } = useParams<{ boardId: string }>()
  const { data: board, isPending } = useBoard(boardId ?? '')
  const { user } = useCurrentUser()
  const deleteLaneMutation = useDeleteLane()

  const handleDeleteLane = (bId: string, laneId: string) => {
    deleteLaneMutation.mutate({ boardId: bId, laneId })
  }

  if (isPending) return <Spinner label="Loading board…" />

  if (!board) return null

  const sortedLanes = [...board.lanes].sort((a, b) => a.position - b.position)

  return (
    <FluentProvider theme={webLightTheme}>
      <div className={styles.root}>
        <div className={styles.header}>
          <Title1 as="h1">{board.name}</Title1>
        </div>
        <div className={styles.lanes}>
          {sortedLanes.map((lane) => (
            <Lane
              key={lane.id}
              lane={lane}
              callerRole={board.callerRole}
              onDelete={handleDeleteLane}
            />
          ))}
        </div>
        {(board.callerRole === 'Owner' ||
          board.callerRole === 'Member' ||
          user?.systemRole === 'admin') && <AddLaneForm boardId={board.id} />}
      </div>
    </FluentProvider>
  )
}

