1	using System.Data;
2	using FluentValidation;
3	using Kanban.Business.Interfaces;
4	using Kanban.Business.Transforms;
5	using Kanban.Contracts;
6	using Kanban.DataAccess.Interfaces;
7	using Kanban.Domain.Entities;
8	using Kanban.Domain.Enums;
9	using Kanban.Domain.Exceptions;
10	using Microsoft.AspNetCore.Authorization;
11	using Microsoft.Extensions.Logging;
12	using Polly;
13	using Polly.Retry;
14	
15	namespace Kanban.Business.Services;
16	
17	public sealed class BoardService : IBoardService
18	{
19	    private readonly IBoardRepository _boardRepository;
20	    private readonly IBoardMemberRepository _boardMemberRepository;
21	    private readonly ICurrentUserService _currentUserService;
22	    private readonly IAuthorizationService _authorizationService;
23	    private readonly IDbConnection _dbConnection;
24	    private readonly IDbConnectionFactory _transactionFactory;
25	    private readonly ILogger<BoardService> _logger;
26	
27	    private static readonly ResiliencePipeline RetryPolicy =
28	        new ResiliencePipelineBuilder()
29	            .AddRetry(new RetryStrategyOptions
30	            {
31	                MaxRetryAttempts = 5,
32	                Delay = TimeSpan.FromMilliseconds(50),
33	                BackoffType = DelayBackoffType.Exponential,
34	                UseJitter = true,
35	                ShouldHandle = new PredicateBuilder().Handle<Exception>(ex =>
36	                    ex.Message.Contains("SQLITE_BUSY", StringComparison.OrdinalIgnoreCase) ||
37	                    ex.Message.Contains("database is locked", StringComparison.OrdinalIgnoreCase)),
38	            })
39	            .Build();
40	
41	    public BoardService(
42	        IBoardRepository boardRepository,
43	        IBoardMemberRepository boardMemberRepository,
44	        ICurrentUserService currentUserService,
45	        IAuthorizationService authorizationService,
46	        IDbConnection dbConnection,
47	        IDbConnectionFactory transactionFactory,
48	        ILogger<BoardService> logger)
49	    {
50	        ArgumentNullException.ThrowIfNull(boardRepository);
51	        ArgumentNullException.ThrowIfNull(boardMemberRepository);
52	        ArgumentNullException.ThrowIfNull(currentUserService);
53	        ArgumentNullException.ThrowIfNull(authorizationService);
54	        ArgumentNullException.ThrowIfNull(dbConnection);
55	        ArgumentNullException.ThrowIfNull(transactionFactory);
56	        ArgumentNullException.ThrowIfNull(logger);
57	        _boardRepository = boardRepository;
58	        _boardMemberRepository = boardMemberRepository;
59	        _currentUserService = currentUserService;
60	        _authorizationService = authorizationService;
61	        _dbConnection = dbConnection;
62	        _transactionFactory = transactionFactory;
63	        _logger = logger;
64	    }
65	
66	    public async Task<BoardDetailDto> CreateAsync(CreateBoardRequest request)
67	    {
68	        new InlineValidator<CreateBoardRequest>
69	            { v => v.RuleFor(x => x.Name).NotEmpty().MaximumLength(200) }
70	            .ValidateAndThrow(request);
71	
72	        var adminAuth = await _authorizationService.AuthorizeAsync(
73	            _currentUserService.Principal, null, "Admin");
74	        if (!adminAuth.Succeeded)
75	            throw new ForbiddenException("board.create_forbidden", "Only admins can create boards.");
76	
77	        var userId = _currentUserService.UserId!.Value;
78	
79	        return await RetryPolicy.ExecuteAsync(async ct =>
80	        {
81	            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
82	            try
83	            {
84	                if (await _boardRepository.ExistsWithNameAsync(request.Name, tx))
85	                    throw new ConflictException("board.name_conflict", "A board with this name already exists.");
86	
87	                var board = new Board(Guid.NewGuid(), request.Name, userId, DateTimeOffset.UtcNow);
88	                await _boardRepository.InsertAsync(board, tx);
89	
90	                var member = new BoardMember(
91	                    Guid.NewGuid(), board.Id, userId, BoardRole.Owner, null, DateTimeOffset.UtcNow);
92	                await _boardMemberRepository.InsertAsync(member, tx);
93	
94	                tx.Commit();
95	                _logger.LogInformation("Board {BoardId} created by user {UserId}", board.Id, userId);
96	                return BoardTransforms.ToDetailDto(board, BoardRole.Owner, []);
97	            }
98	            catch
99	            {
100	                tx.Rollback();
101	                throw;
102	            }
103	        });
104	    }
105	
106	    public async Task<IReadOnlyList<BoardSummaryDto>> ListForCallerAsync()
107	    {
108	        var userId = _currentUserService.UserId!.Value;
109	        var boards = await _boardRepository.FindBoardsForUserAsync(userId);
110	
111	        var summaries = new List<BoardSummaryDto>(boards.Count);
112	        foreach (var board in boards)
113	        {
114	            var role = await _boardMemberRepository.FindRoleAsync(board.Id, userId)
115	                ?? BoardRole.Viewer;
116	            summaries.Add(BoardTransforms.ToSummaryDto(board, role, 0, 0));
117	        }
118	        return summaries;
119	    }
120	
121	    public async Task<BoardDetailDto> GetAsync(Guid boardId)
122	    {
123	        new InlineValidator<Guid>
124	            { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }
125	            .ValidateAndThrow(boardId);
126	
127	        var userId = _currentUserService.UserId!.Value;
128	        var board = await _boardRepository.FindBoardForMemberAsync(boardId, userId)
129	            ?? throw new NotFoundException("board.not_found", "Board not found.");
130	
131	        var role = await _boardMemberRepository.FindRoleAsync(boardId, userId)
132	            ?? BoardRole.Viewer;
133	
134	        return BoardTransforms.ToDetailDto(board, role, []);
135	    }
136	
137	    public async Task DeleteAsync(Guid boardId)
138	    {
139	        new InlineValidator<Guid>
140	            { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }
141	            .ValidateAndThrow(boardId);
142	
143	        var userId = _currentUserService.UserId!.Value;
144	        _ = await _boardRepository.FindBoardForMemberAsync(boardId, userId)
145	            ?? throw new NotFoundException("board.not_found", "Board not found.");
146	
147	        var deleteAuth = await _authorizationService.AuthorizeAsync(
148	            _currentUserService.Principal, new BoardContext(boardId),
149	            new BoardMembershipRequirement(BoardOperations.DeleteBoard));
150	        if (!deleteAuth.Succeeded)
151	            throw new ForbiddenException("board.delete_forbidden", "You do not have permission to delete this board.");
152	
153	        await RetryPolicy.ExecuteAsync(async ct =>
154	        {
155	            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
156	            try
157	            {
158	                await _boardRepository.DeleteAsync(boardId, tx);
159	                tx.Commit();
160	                _logger.LogInformation("Board {BoardId} deleted by user {UserId}", boardId, userId);
161	            }
162	            catch
163	            {
164	                tx.Rollback();
165	                throw;
166	            }
167	        });
168	    }
169	}
