import { useMutation, useQueryClient } from '@tanstack/react-query'
import type { ApiError, BoardSummary } from './useBoards'

async function createBoard(name: string): Promise<BoardSummary> {
  const response = await fetch('/api/v1/boards', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ name }),
  })
  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw { status: response.status, code: body.code, title: body.title } as ApiError
  }
  return response.json() as Promise<BoardSummary>
}

export function useCreateBoard() {
  const queryClient = useQueryClient()
  return useMutation<BoardSummary, ApiError, { name: string }>({
    mutationFn: ({ name }) => createBoard(name),
    onSettled: () => queryClient.invalidateQueries({ queryKey: ['boards'] }),
    retry: false,
  })
}

import {
  Button,
  Dialog,
  DialogActions,
  DialogBody,
  DialogContent,
  DialogSurface,
  DialogTitle,
  DialogTrigger,
  Input,
  Label,
  MessageBar,
  MessageBarBody,
  makeStyles,
  tokens,
} from '@fluentui/react-components'
import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useCreateBoard } from '../../hooks/useCreateBoard'

const useStyles = makeStyles({
  field: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalXS,
  },
  alert: {
    marginBottom: tokens.spacingVerticalS,
  },
})

export default function CreateBoardDialog() {
  const styles = useStyles()
  const navigate = useNavigate()
  const [open, setOpen] = useState(false)
  const [name, setName] = useState('')
  const { mutate, isPending, isError, error, reset } = useCreateBoard()

  const handleSubmit = () => {
    const trimmed = name.trim()
    if (!trimmed) return
    mutate(
      { name: trimmed },
      {
        onSuccess: (board) => {
          setName('')
          setOpen(false)
          navigate(`/boards/${board.id}`)
        },
      }
    )
  }

  return (
    <Dialog
      open={open}
      onOpenChange={(_, d) => {
        setOpen(d.open)
        if (!d.open) {
          setName('')
          reset()
        }
      }}
    >
      <DialogTrigger disableButtonEnhancement>
        <Button appearance="primary" aria-label="Create board">
          Create Board
        </Button>
      </DialogTrigger>
      <DialogSurface>
        <DialogBody>
          <DialogTitle>Create Board</DialogTitle>
          <DialogContent>
            {isError && (
              <MessageBar role="alert" intent="error" className={styles.alert}>
                <MessageBarBody>{error?.title ?? 'Failed to create board'}</MessageBarBody>
              </MessageBar>
            )}
            <div className={styles.field}>
              <Label htmlFor="board-name">Board name</Label>
              <Input
                id="board-name"
                aria-label="Board name"
                value={name}
                onChange={(_, d) => setName(d.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') handleSubmit()
                }}
              />
            </div>
          </DialogContent>
          <DialogActions>
            <Button
              appearance="primary"
              disabled={!name.trim() || isPending}
              onClick={handleSubmit}
            >
              Create
            </Button>
            <DialogTrigger disableButtonEnhancement>
              <Button appearance="secondary">Cancel</Button>
            </DialogTrigger>
          </DialogActions>
        </DialogBody>
      </DialogSurface>
    </Dialog>
  )
}

using Kanban.Business.Interfaces;
using Kanban.Contracts;

namespace Kanban.Api.Endpoints;

public static class CardEndpoints
{
    public static void Map(IEndpointRouteBuilder routes)
    {
        var cards = routes.MapGroup("/boards/{boardId:guid}");

        cards.MapPost("lanes/{laneId:guid}/cards",
            async (Guid boardId, Guid laneId, CreateCardRequest request, ICardService cardService) =>
            {
                var card = await cardService.CreateAsync(boardId, laneId, request);
                return Results.Created($"/api/v1/boards/{boardId}/cards/{card.Id}", card);
            })
            .WithName("CreateCard")
            .WithSummary("Create a card in a lane")
            .Produces<CardDto>(201)
            .ProducesProblem(403)
            .ProducesProblem(404)
            .ProducesProblem(422)
            .RequireRateLimiting("mutating");

        cards.MapPatch("cards/{cardId:guid}",
            async (Guid boardId, Guid cardId, UpdateCardRequest request, ICardService cardService) =>
                Results.Ok(await cardService.UpdateAsync(boardId, cardId, request)))
            .WithName("UpdateCard")
            .WithSummary("Update a card's fields")
            .Produces<CardDto>(200)
            .ProducesProblem(403)
            .ProducesProblem(404)
            .ProducesProblem(422)
            .RequireRateLimiting("mutating");

        cards.MapDelete("cards/{cardId:guid}",
            async (Guid boardId, Guid cardId, ICardService cardService) =>
            {
                await cardService.DeleteAsync(boardId, cardId);
                return Results.NoContent();
            })
            .WithName("DeleteCard")
            .WithSummary("Delete a card")
            .Produces(204)
            .ProducesProblem(403)
            .ProducesProblem(404)
            .RequireRateLimiting("mutating");

        cards.MapPost("cards/{cardId:guid}/move",
            async (Guid boardId, Guid cardId, MoveCardRequest request, ICardService cardService) =>
                Results.Ok(await cardService.MoveAsync(boardId, cardId, request)))
            .WithName("MoveCard")
            .WithSummary("Move a card to a new lane/position")
            .Produces<CardDto>(200)
            .ProducesProblem(403)
            .ProducesProblem(404)
            .ProducesProblem(409)
            .RequireRateLimiting("mutating");
    }
}

